const Row = ({ children }) => <div className="flex flex-wrap items-center gap-x-6 gap-y-3">{children}</div>;

const ANGLES = [90, 60, 30];

const Component = () => {
  const [miterLimit, setMiterLimit] = useState(2);
  const ref = useCanvas((ctx, { width, color }) => {
    const column = width / ANGLES.length;
    ANGLES.forEach((angle, index) => {
      const radians = (angle * Math.PI) / 180;
      const cx = column * index + column / 2;
      const cy = 56;
      const length = Math.min(column * 0.36, 80);
      ctx.beginPath();
      ctx.lineJoin = "miter";
      ctx.miterLimit = miterLimit;
      ctx.lineWidth = 12;
      ctx.strokeStyle = color("ink-2");
      ctx.moveTo(cx - Math.sin(radians / 2) * length, cy + Math.cos(radians / 2) * length);
      ctx.lineTo(cx, cy);
      ctx.lineTo(cx + Math.sin(radians / 2) * length, cy + Math.cos(radians / 2) * length);
      ctx.stroke();
      // 斜接长度与线宽之比 = 1 / sin(θ/2)，超过 miterLimit 时尖角被截平
      const ratio = 1 / Math.sin(radians / 2);
      note(ctx, color, `${angle}° · 比值 ${ratio.toFixed(2)}`, cx, 172, "center");
      note(ctx, color, ratio > miterLimit ? "超出 → 斜角" : "未超出 → 尖角", cx, 194, "center");
    });
  }, [miterLimit]);

  return (
    <Demo>
      <Stage canvasRef={ref} height={212} />
      <Row>
        <Slider label="miterLimit" value={miterLimit} min={1} max={5} step={0.1} onChange={setMiterLimit} format={value => value.toFixed(1)} />
        <Chip>ctx.miterLimit = {miterLimit.toFixed(1)}</Chip>
      </Row>
    </Demo>
  );
};
